    void syncMode(){if(messageMode==null||plain==null||secretControls==null)return;boolean image=messageMode.getSelectedItemPosition()==1;secretControls.setVisibility(image?View.VISIBLE:View.GONE);if(encSecretCard!=null)encSecretCard.setVisibility(image?View.VISIBLE:View.GONE);if(plainTitle!=null)plainTitle.setVisibility(image?View.GONE:View.VISIBLE);plain.setVisibility(image?View.GONE:View.VISIBLE);count.setVisibility(image?View.GONE:View.VISIBLE);if(keyboardDone!=null)keyboardDone.setVisibility(image?View.GONE:View.VISIBLE);lossless.setVisibility(image?View.VISIBLE:View.GONE);if(strength!=null)strength.setEnabled(!busy&&!(image&&lossless.isChecked()));if(saveImage!=null){saveImage.setEnabled(!busy&&decodedPayload!=null);saveImage.setVisibility(decodedPayload==null?View.GONE:View.VISIBLE);}if(copyText!=null){copyText.setEnabled(!busy&&decodedPayload==null);copyText.setVisibility(decodedPayload==null?View.VISIBLE:View.GONE);}}
