    void decrypt()throws Exception{if(decodeUri==null)throw Crypto.error("请先选择载体PNG。");final Uri uri=decodeUri;final String key=selectedKey(1);clearResult();runJob("正在读取图片…",()->{Transport.Result result=Transport.decode(Images.load(this,uri),key,this::update);Bitmap preview=null;if(result.image!=null){SecretImages.validate(result.image);preview=SecretImages.payloadPreview(result.image);}return new Object[]{result,preview};},obj->{Object[]values=(Object[])obj;Transport.Result r=(Transport.Result)values[0];SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.CHINA);f.setTimeZone(TimeZone.getTimeZone("GMT+08:00"));resultTime.setText("生成时间（北京时间）："+f.format(new Date(r.message.seconds*1000)));decodedPayload=r.image;if(r.image==null){resultText.setText(r.message.text);}else{ImagePayload.Prepared image=r.image;decSecretCard.setVisibility(View.VISIBLE);decodedPreview.setImageBitmap((Bitmap)values[1]);resultText.setText((image.png?"PNG无损":"JPG")+"图片已通过认证。\n尺寸："+image.width+"×"+image.height+String.format(Locale.CHINA,"\n大小：%.1f KiB",image.data.length/1024.)+(image.png?"\n需要完整载体，不支持裁剪。":""));saveImage.setText(image.png?"保存图片为PNG":"保存图片为JPG");}status.setText("解密成功 · 消息已通过完整性验证。");syncMode();});}
    void passwordDialog(String title,boolean confirm,java.util.function.Consumer<char[]>accepted){LinearLayout l=column();l.setPadding(dp(20),dp(8),dp(20),0);EditText first=edit("至少12个字符",false),second=edit("再次输入密码",false);for(EditText e:new EditText[]{first,second}){e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);e.setTransformationMethod(PasswordTransformationMethod.getInstance());}l.addView(first);if(confirm)l.addView(second);addButton(l,"收起键盘",this::hideKeyboard);AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setView(l).setNegativeButton("取消",null).setPositiveButton("继续",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->attempt(()->{String p=first.getText().toString();if(p.length()<12)throw Crypto.error("备份密码至少12个字符。");if(confirm&&!p.equals(second.getText().toString()))throw Crypto.error("两次输入的密码不一致。");hideKeyboard();char[]chars=p.toCharArray();first.setText("");second.setText("");d.dismiss();accepted.accept(chars);})));d.show();}
