    void restore(){passwordDialog("输入备份密码",false,password->{restorePassword=password;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,OPEN_BACKUP);});}
