    @Override public void onBackPressed(){if(busy){new AlertDialog.Builder(this).setTitle("取消当前操作？").setNegativeButton("继续等待",null).setPositiveButton("取消操作",(d,w)->{requestCancel();}).show();}else super.onBackPressed();}
    @Override protected void onDestroy(){destroyed=true;requestCancel();worker.shutdownNow();if(pendingPng!=null)pendingPng.delete();if(pendingBackup!=null)Arrays.fill(pendingBackup,(byte)0);if(restorePassword!=null)Arrays.fill(restorePassword,'\0');if(pendingImage!=null)Arrays.fill(pendingImage,(byte)0);decodedPayload=null;super.onDestroy();}
